 50	/** Discount in integer cents for a coupon on an order of `amountCents`. */
 51	export function computeDiscount(amountCents: number, coupon: Coupon): number {
 52	  const raw = coupon.type === "FIXED" ? coupon.value : Math.floor((amountCents * coupon.value) / 100);
 53	  const capped = coupon.maxDiscountCents === null ? raw : Math.min(raw, coupon.maxDiscountCents);
 54	  return Math.max(0, Math.min(capped, amountCents));
 55	}
